officialChampionsFixtures.forEach(match=>{const round=championsData.rounds.find(item=>item.round===match.round);if(!round)return;const existing=round.matches.find(item=>item.home===match.home&&item.away===match.away);if(existing)Object.assign(existing,match);else round.matches.push(match);});
